  1	/**
  2	 * Hermes executor entrypoint — ABI-conformant.
  3	 *
  4	 * Reads ExecutorInput from environment variables, runs phases 1–5, then
  5	 * post-execution (Phase 6) commits, pushes, opens the impl PR, and writes result.json.
  6	 *
  7	 * Formal ABI env vars (from ExecutorInput):
  8	 *   TASK_ID, FEATURE_ID, WORKSPACE_ID, HANDLE
  9	 *   TASK_REPO_URL, TASK_REPO_BRANCH, TASK_BASE_BRANCH, TASK_REPO_BASE_BRANCH
 10	 *   EXECUTOR_WORKDIR, MGMT_REPO_URL
 11	 *   RESULT_PATH
 12	 *   SSH_PRIVATE_KEY, GITHUB_TOKEN
 13	 *
 14	 * Hermes-specific env vars (injected via SubProcessAdapterOpts.extraEnv):
 15	 *   HERMES_INFERENCE_MODEL    — model ID (e.g. deepseek-v4-flash)
 16	 *   HERMES_INFERENCE_PROVIDER — provider (e.g. deepseek)
 17	 *   HERMES_MAX_TURNS          — max tool iterations (default 150)
 18	 *   RAG_MCP_URL               — optional RAG MCP server URL
 19	 *   RAG_MCP_TOKEN             — optional RAG MCP auth token
 20	 *
 21	 * Startup phases:
 22	 *   Phase 1: clone management repo (read-only)
 23	 *   Phase 2: clone implementation repo onto TASK_REPO_BRANCH
 24	 *   Phase 3: write HERMES_HOME/config.yaml (model + optional MCP stanza)
 25	 *   Phase 4: build briefing from mgmt clone
 26	 *   Phase 5: spawn hermes chat in try/finally (recovery fires in finally)
 27	 *   Phase 6: wrapper commits + pushes + opens impl PR + writes result.json [T4]
 28	 */
 29	
 30	import { spawn, execSync } from "node:child_process";
 31	import {
 32	  mkdirSync,
 33	  writeFileSync,
 34	  existsSync,
 35	  rmSync,
 36	} from "node:fs";
 37	import { join, dirname } from "node:path";
 38	import { stringify as yamlStringify } from "yaml";
 39	import type { ExecutorResult } from "@workflow/runtime-abi";
 40	import { runRecovery, type SpawnResult } from "./recovery.js";
 41	import { buildBriefing } from "./briefing.js";
 42	import { resolveSSHKey } from "./resolve-ssh-key.js";
 43	import { buildGitEnv } from "./git-env.js";
 44	
 45	// ── Helpers ────────────────────────────────────────────────────────────────────
 46	
 47	function requireEnv(name: string): string {
 48	  const val = process.env[name];
 49	  if (!val) throw new Error(`Required env var ${name} is not set`);
 50	  return val;
 51	}
 52	
 53	function emit(event: Record<string, unknown>): void {
 54	  console.log(JSON.stringify({ at: new Date().toISOString(), ...event }));
 55	}
 56	
 57	function writeResult(resultPath: string, result: ExecutorResult): void {
 58	  mkdirSync(dirname(resultPath), { recursive: true });
 59	  writeFileSync(resultPath, JSON.stringify(result), "utf-8");
 60	}
 61	
 62	// ── Phase 1 + 2: repo materialisation ─────────────────────────────────────────
 63	
 64	/**
 65	 * Clone or pull a repo at targetDir on the given branch.
 66	 * If targetDir already contains a valid clone of the same URL,
 67	 * fetch + checkout + pull instead of re-cloning.
 68	 */
 69	export function cloneOrPull(
 70	  url: string,
 71	  targetDir: string,
 72	  branch: string,
 73	  sshKeyPath: string | undefined,
 74	): void {
 75	  const env = buildGitEnv(sshKeyPath);
 76	  const opts = { env, stdio: "pipe" as const };
 77	
 78	  if (existsSync(join(targetDir, ".git"))) {
 79	    let originUrl = "";
 80	    try {
 81	      originUrl = execSync(`git -C "${targetDir}" remote get-url origin`, {
 82	        ...opts, encoding: "utf-8",
 83	      }).trim();
 84	    } catch { /* no remote — fall through to clone */ }
 85	
 86	    if (originUrl === url) {
 87	      execSync(`git -C "${targetDir}" fetch origin`, opts);
 88	      try {
 89	        execSync(`git -C "${targetDir}" checkout -- .`, opts);
 90	      } catch { /* ignore */ }
 91	      try {
 92	        execSync(`git -C "${targetDir}" checkout "${branch}"`, opts);
 93	      } catch {
 94	        execSync(`git -C "${targetDir}" checkout -b "${branch}"`, opts);
 95	      }
 96	      try {
 97	        execSync(`git -C "${targetDir}" pull --ff-only origin "${branch}"`, opts);
 98	      } catch {
 99	        emit({ type: "repo_pull_diverged", dir: targetDir, branch, note: "ff-only failed — using checked-out ref" });
100	      }
101	      return;
102	    }
103	  }
104	
105	  mkdirSync(dirname(targetDir), { recursive: true });
106	  if (existsSync(targetDir)) {
107	    rmSync(targetDir, { recursive: true, force: true });
108	  }
109	  execSync(`git clone "${url}" "${targetDir}"`, opts);
110	  try {
111	    execSync(`git -C "${targetDir}" checkout "${branch}"`, opts);
112	  } catch {
113	    execSync(`git -C "${targetDir}" checkout -b "${branch}"`, opts);
114	  }
115	}
116	
117	/**
118	 * Materialize the management repo on the task branch.
119	 * Falls back to main if the task branch is not yet on origin.
120	 */
121	export function materializeMgmtRepo(
122	  mgmtRepoUrl: string,
123	  mgmtDir: string,
124	  sshKeyPath: string | undefined,
125	  taskBranch: string,
126	): void {
127	  const env = buildGitEnv(sshKeyPath);
128	  const opts = { env, stdio: "pipe" as const };
129	
130	  const checkoutTaskBranch = (dir: string): void => {
131	    try {
132	      execSync(`git -C "${dir}" checkout -B "${taskBranch}" "origin/${taskBranch}"`, opts);
133	    } catch (taskBranchErr) {
134	      try {
135	        execSync(`git -C "${dir}" checkout main`, opts);
136	      } catch (e) {
137	        emit({ type: "mgmt_repo_checkout_failed", dir, branch: "main", details: String(e) });
138	      }
139	      try {
140	        execSync(`git -C "${dir}" pull --ff-only origin main`, opts);
141	      } catch {
142	        emit({ type: "mgmt_repo_pull_diverged", dir, note: "ff-only failed", task_branch_err: String(taskBranchErr) });
143	      }
144	    }
145	  };
146	
147	  if (existsSync(join(mgmtDir, ".git"))) {
148	    let originUrl = "";
149	    try {
150	      originUrl = execSync(`git -C "${mgmtDir}" remote get-url origin`, {
151	        ...opts, encoding: "utf-8",
152	      }).trim();
153	    } catch { /* no remote */ }
154	
155	    if (originUrl === mgmtRepoUrl) {
156	      execSync(`git -C "${mgmtDir}" fetch origin`, opts);
157	      checkoutTaskBranch(mgmtDir);
158	      return;
159	    }
160	  }
161	
162	  mkdirSync(dirname(mgmtDir), { recursive: true });
163	  if (existsSync(mgmtDir)) {
164	    rmSync(mgmtDir, { recursive: true, force: true });
165	  }
166	  execSync(`git clone "${mgmtRepoUrl}" "${mgmtDir}"`, opts);
167	  checkoutTaskBranch(mgmtDir);
168	}
