170	// ── Phase 3: Hermes config ─────────────────────────────────────────────────────
171	
172	export interface HermesConfig {
173	  provider: string;
174	  model: string;
175	  ragMcpUrl?: string;
176	  ragMcpToken?: string;
177	}
178	
179	/**
180	 * Write HERMES_HOME/config.yaml with model stanza and optional RAG MCP stanza.
181	 * No memory stanza — stateless by default (Mem0 is hermes-workspace-memory scope).
182	 */
183	export function writeHermesConfig(hermesHome: string, config: HermesConfig): void {
184	  mkdirSync(hermesHome, { recursive: true });
185	
186	  const configObj: Record<string, unknown> = {
187	    model: {
188	      provider: config.provider,
189	      default: config.model,
190	    },
191	  };
192	
193	  if (config.ragMcpUrl) {
194	    configObj.mcp_servers = {
195	      rag: {
196	        url: config.ragMcpUrl,
197	        ...(config.ragMcpToken
198	          ? { headers: { Authorization: `Bearer ${config.ragMcpToken}` } }
199	          : {}),
200	      },
201	    };
202	  }
203	
204	  writeFileSync(join(hermesHome, "config.yaml"), yamlStringify(configObj), "utf-8");
205	}
206	
207	// ── Phase 5: Hermes spawn ──────────────────────────────────────────────────────
208	
209	interface HermesSpawnOpts {
210	  briefing: string;
211	  hermesHome: string;
212	  hermesModel: string;
213	  hermesProvider: string;
214	  hermesMaxTurns: string;
215	  taskRepoPath: string;
216	}
217	
218	function spawnHermes(opts: HermesSpawnOpts): Promise<SpawnResult> {
219	  const {
220	    briefing,
221	    hermesHome,
222	    hermesModel,
223	    hermesProvider,
224	    hermesMaxTurns,
225	    taskRepoPath,
226	  } = opts;
227	
228	  return new Promise((resolve) => {
229	    const env: NodeJS.ProcessEnv = {
230	      ...process.env,
231	      HERMES_HOME: hermesHome,
232	      HERMES_INFERENCE_MODEL: hermesModel,
233	      HERMES_INFERENCE_PROVIDER: hermesProvider,
234	      HERMES_MAX_ITERATIONS: hermesMaxTurns,
235	      HERMES_YOLO_MODE: "1",
236	    };
237	
238	    const child = spawn(
239	      "hermes",
240	      ["chat", "--query", briefing, "--quiet", "--ignore-rules"],
241	      {
242	        cwd: taskRepoPath,
243	        env,
244	        stdio: ["ignore", "pipe", "pipe"],
245	      },
246	    );
247	
248	    let stdout = "";
249	    child.stdout.on("data", (chunk: Buffer) => {
250	      stdout += chunk.toString();
251	    });
252	    child.stderr.on("data", (chunk: Buffer) => {
253	      process.stderr.write(chunk);
254	    });
255	
256	    child.on("error", (error: Error) => {
257	      resolve({ stdout, status: null, signal: null, error });
258	    });
259	
260	    child.on("close", (code: number | null, signal: NodeJS.Signals | null) => {
261	      resolve({ stdout, status: code, signal });
262	    });
263	  });
264	}
